Open Scope Z_scope.

(* [comment removed for export] *)
Definition SOBUF : Z := 6924704.
Definition stdoutA (j : Z) (MV : word -> option byte) : Prop :=
  rdn ASEGS MV (Z_to_bv 64 1319360) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 5))                       (* [comment removed for export] *)
  /\ rdn ASEGS MV (Z_to_bv 64 1319456) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 1024))                 (* [comment removed for export] *)
  /\ rdn ASEGS MV (Z_to_bv 64 1319392) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (SOBUF + 1024)))       (* [comment removed for export] *)
  /\ rdn ASEGS MV (Z_to_bv 64 1319400) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (SOBUF + 2 * j)))      (* [comment removed for export] *)
  /\ rdn ASEGS MV (Z_to_bv 64 1319416) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 SOBUF))                (* [comment removed for export] *)
  /\ rdn ASEGS MV (Z_to_bv 64 1319500) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 4294967295))           (* [comment removed for export] *)
  /\ rdn ASEGS MV (Z_to_bv 64 1319504) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 4294967295))           (* [comment removed for export] *)
  /\ (forall a n, 1319360 <= a -> a + n <= 1319360 + 232 -> forall d (k : nat), 0 <= d -> d + Z.of_nat k <= n -> store_ok ASEGS MV (Z_to_bv 64 (a + d)) k = true)
  /\ (forall a n, SOBUF <= a -> a + n <= SOBUF + 1024 -> forall d (k : nat), 0 <= d -> d + Z.of_nat k <= n -> store_ok ASEGS MV (Z_to_bv 64 (a + d)) k = true)
  /\ (forall i, 0 <= i < j -> rdn ASEGS MV (Z_to_bv 64 (SOBUF + 2 * i)) 1 = Some [Z_to_bv 8 48] /\ rdn ASEGS MV (Z_to_bv 64 (SOBUF + 2 * i + 1)) 1 = Some [Z_to_bv 8 10]).

(* [comment removed for export] *)
Definition Wpf (S j a : Z) : Prop :=
  S - 3232 <= a < S \/ 1319360 <= a < 1319364 \/ 1319400 <= a < 1319408 \/ SOBUF + 2 * j <= a < SOBUF + 2 * j + 2.

Section FPX_1. Context {fx : PropExec.FPState}.
Variable scfg : SpuriousCfg.
Section PrintfK.
  Variable L : asan_layout.
  Variable ar : asan_run.
  Variable C : asan_statics_cells.
  Variable IL : icpt_layout.
  Variable HI : asan_iface.
  Hypothesis HIok : asan_iface_okB L ar C scfg HI.
  Hypothesis ICok : aicpt_ok L ar IL scfg HI.
  Hypothesis ILY : as0_icpt_layout IL.
  Variable sp0 : word.
  Hypothesis Hsp : 0x7fff80000000 <= bv_unsigned sp0 <= 2 ^ 47.
  Hypothesis Hal : bv_unsigned sp0 mod 16 = 0.
  Hypothesis DL : drv_layoutA L ar IL sp0.
  Hypothesis Hpr : incl PR_CELLS (asc_cells C).
  Variable M0 : word -> option byte.
  #[local] Notation dinvA := (dinv ar HI sp0 M0).
  #[local] Notation usp := (bv_unsigned sp0).
  #[local] Notation rom := (seg_rom ASEGS).

  #[using="L C IL HIok ICok ILY Hsp DL Hpr"] Lemma printf2_run : forall LB LK cr A M (model : Model) R (S canz : Z) K,
    dinvA LB LK cr A M model ->
    let MV := mrestrict (ahid A model) M in
    usp - 4096 <= S -> S + 32 <= usp -> S mod 16 = 0 -> 0 <= canz < 2 ^ 64 ->
    getr R 1%bv = Z_to_bv 64 692548 -> getr R 2%bv = Z_to_bv 64 S -> getr R 10%bv = Z_to_bv 64 85823 -> getr R 11%bv = Z_to_bv 64 (S + 24) ->
    (forall a n, usp - 8388608 <= a -> a + n <= usp -> forall d (k : nat), 0 <= d -> d + Z.of_nat k <= n -> store_ok ASEGS MV (Z_to_bv 64 (a + d)) k = true) ->
    (forall i, 65536 <= i < 1306624 -> MV (Z_to_bv 64 i) = None) ->
    rdn ASEGS MV (Z_to_bv 64 6922688) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 canz)) ->
    rdn ASEGS MV (Z_to_bv 64 (S + 24)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 0)) ->
    stdoutA 0 MV ->
    (forall (fx' : PropExec.FPState) R' M1 (model1 : Model),
        dinvA LB LK cr A M1 model1 -> same_but_materialized model model1 ->
        (forall x, In x AS0DRVP_dpA2.KS_dpA2 -> getr R' (Z_to_bv 5 (Z.of_nat x)) = getr R (Z_to_bv 5 (Z.of_nat x))) ->
        getr R' 10%bv = Z_to_bv 64 2 ->
        stdoutA 1 (mrestrict (ahid A model1) M1) ->
        (forall a, 0 <= a < 2 ^ 64 -> ~ Wpf S 0 a -> M1 (Z_to_bv 64 a) = M (Z_to_bv 64 a)) ->
        (forall a, 0 <= a < 2 ^ 64 -> ~ Wpf S 0 a -> mrestrict (ahid A model1) M1 (Z_to_bv 64 a) = MV (Z_to_bv 64 a)) ->
        (forall a : word, MV a <> None -> mrestrict (ahid A model1) M1 a <> None) ->
        srealizes ASEGS scfg (mkCfg (@mkst fx' R' (Z_to_bv 64 0xa9144) M1 rom) model1) K) ->
    srealizes ASEGS scfg (mkCfg (@mkst fx R (Z_to_bv 64 0x64558) M rom) model) K.
Proof.
Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(true).
